import '@shopify/ui-extensions/preact';
import {render} from 'preact';
import {useState, useEffect} from 'preact/hooks';

export default async () =&gt; {
  render(&lt;Extension /&gt;, document.body);
};

const API_VERSION = '2026-01';

function Extension() {
  const [name, setName] = useState(null);

  useEffect(() =&gt; {
    fetch(
      `shopify://customer-account/api/${API_VERSION}/graphql.json`,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          query: `query {
            customer {
              firstName
              lastName
            }
          }`,
        }),
      },
    )
      .then((response) =&gt; response.json())
      .then(({data: {customer}}) =&gt; {
        if (!customer) return;
        setName(customer);
      })
      .catch(console.error);
  }, []);

  if (!name) {
    return &lt;s-text&gt;Loading…&lt;/s-text&gt;;
  }

  return (
    &lt;s-box padding="base"&gt;
      &lt;s-text type="strong"&gt;
        Hello, {name.firstName} {name.lastName}!
      &lt;/s-text&gt;
    &lt;/s-box&gt;
  );
}

// @extension-target: customer-account.order-status.block.render
import '@shopify/ui-extensions/preact';
import {render} from 'preact';
import {useState, useEffect} from 'preact/hooks';

export default async () =&gt; {
  render(&lt;Extension /&gt;, document.body);
};

const API_VERSION = '2026-01';

function Extension() {
  const [orders, setOrders] = useState(null);

  useEffect(() =&gt; {
    fetch(
      `shopify://customer-account/api/${API_VERSION}/graphql.json`,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          query: `query {
            customer {
              orders(first: 5) {
                edges {
                  node {
                    name
                    totalPrice {
                      amount
                    }
                  }
                }
              }
            }
          }`,
        }),
      },
    )
      .then((response) =&gt; response.json())
      .then(({data: {customer}}) =&gt; {
        if (!customer) return;
        setOrders(
          customer.orders.edges.map(
            (edge) =&gt; edge.node,
          ),
        );
      })
      .catch(console.error);
  }, []);

  if (!orders) {
    return &lt;s-text&gt;Loading orders…&lt;/s-text&gt;;
  }

  return (
    &lt;s-box padding="base"&gt;
      &lt;s-stack direction="block" gap="small-200"&gt;
        &lt;s-text type="strong"&gt;
          Recent Orders
        &lt;/s-text&gt;
        {orders.map((order) =&gt; (
          &lt;s-stack
            key={order.name}
            direction="inline"
            gap="base"
          &gt;
            &lt;s-text type="strong"&gt;
              {order.name}
            &lt;/s-text&gt;
            &lt;s-text&gt;
              ${order.totalPrice.amount}
            &lt;/s-text&gt;
          &lt;/s-stack&gt;
        ))}
      &lt;/s-stack&gt;
    &lt;/s-box&gt;
  );
}

