import '@shopify/ui-extensions/preact';
import {render} from 'preact';

export default async () =&gt; {
  render(&lt;Extension /&gt;, document.body);
};

function Extension() {
  const order = shopify.order.value;

  if (order) {
    return (
      &lt;s-banner&gt;
        Please include your order ID ({order.id})
        in support requests
      &lt;/s-banner&gt;
    );
  }

  return null;
}

